import {briefFields,cleanBrief,questionFor,teamBrief,guidedCopy,renderBusinessDraft,appPlan} from './business-builder-core.js';
const $=id=>document.getElementById(id),dialog=$('business-builder-dialog');let brief={},field=0,draft=null,copy=null,context=null,token=0,working=false,recognition=null,controller=null;
const say=value=>{$('builder-guide-status').textContent=value;};
function el(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;}
function invalidate(){draft=null;copy=null;$('builder-apply').disabled=true;$('builder-review').hidden=true;}
function stopVoice(){if(recognition){recognition.onresult=null;recognition.onend=null;recognition.abort();recognition=null;}$('builder-voice').textContent='Speak answer';}
function question(){stopVoice();$('builder-question').textContent=questionFor(briefFields[field],brief);$('builder-answer').value=brief[briefFields[field]]||'';$('builder-progress').textContent=(field+1)+' / '+briefFields.length;$('builder-back').disabled=working||field===0;$('builder-next').textContent=field===briefFields.length-1?'Review answers':'Next';$('builder-answer').focus();}
function saveAnswer(){brief[briefFields[field]]=$('builder-answer').value;brief=cleanBrief(brief);}
function controls(){for(const id of ['builder-back','builder-next','builder-guided','builder-ai','builder-plan','builder-answer','builder-change'])$(id).disabled=working;$('builder-back').disabled=working||field===0;$('builder-voice').disabled=working||!(window.SpeechRecognition||window.webkitSpeechRecognition);$('builder-apply').disabled=working||!draft;}
function review(result,source){copy=result;draft=renderBusinessDraft(brief,result);$('builder-review').hidden=false;$('builder-source').textContent=source;const frag=document.createDocumentFragment();
 for(const member of teamBrief(brief)){const card=el('article');card.append(el('h3',member.role),el('p',member.message),el('p',member.question));frag.append(card);}$('builder-team').replaceChildren(frag);
 $('builder-customer-pitch').textContent=result.customerPitch;$('builder-investor-pitch').textContent=result.investorPitch;$('builder-advice').textContent=result.advice;
 $('builder-draft-frame').srcdoc='<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>'+draft.css+'</style></head><body>'+draft.html+'</body></html>';controls();say('Review the draft and briefings. Apply changes, then save and publish in the editor.');
}
$('business-builder').onclick=async()=>{if(!window.bongaWebsiteBuilder){say('The editor is still opening. Try again.');return;}if(window.bongaWebsiteBuilder.context().busy)return;brief={...(window.bongaWebsiteBuilder.context().brief||{})};field=0;invalidate();dialog.showModal();question();controls();const current=++token;try{const r=await fetch('/api/builder/assistant',{cache:'no-store'}),data=await r.json();if(current!==token)return;$('builder-ai-state').textContent=r.ok?data.setup:data.error;}catch{if(current===token)$('builder-ai-state').textContent='AI availability could not be checked. Guided drafts remain available.';}};
$('builder-guide-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{token++;controller?.abort();controller=null;working=false;stopVoice();controls();});
$('builder-answer').addEventListener('input',invalidate);$('builder-change').addEventListener('input',invalidate);
$('builder-next').onclick=()=>{try{saveAnswer();invalidate();if(field<briefFields.length-1){field++;question();}else{say('Answers ready. Create a guided draft or request AI copy.');$('builder-guided').focus();}}catch(e){say(e.message);}};
$('builder-back').onclick=()=>{try{saveAnswer();field=Math.max(0,field-1);invalidate();question();}catch(e){say(e.message);}};
$('builder-guided').onclick=()=>{try{saveAnswer();context=window.bongaWebsiteBuilder.context();review(guidedCopy(brief),'Guided draft from your answers · no AI call');}catch(e){say(e.message);}};
$('builder-ai').onclick=async()=>{if(working)return;let current;try{saveAnswer();guidedCopy(brief);stopVoice();context=window.bongaWebsiteBuilder.context();invalidate();working=true;controls();current=++token;controller=new AbortController();say('The AI team is preparing copy from your brief…');const r=await fetch('/api/builder/assistant',{method:'POST',signal:controller.signal,headers:{'content-type':'application/json'},body:JSON.stringify({brief,change:$('builder-change').value})}),data=await r.json();if(current!==token)return;if(!r.ok)throw Error(data.error||'AI generation failed.');review(data.copy,data.source);}catch(e){if(current===undefined||current===token)say(e.message);}finally{if(current===undefined||current===token){working=false;controller=null;controls();}}};
$('builder-apply').onclick=()=>{if(!draft||working)return;try{const result=window.bongaWebsiteBuilder.apply(draft,context);if(!result.ok)throw Error(result.error);dialog.close();}catch(e){say(e.message);}};
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('builder-plan').onclick=()=>{try{saveAnswer();download(appPlan(brief),'business-app-plan.json');say('App implementation plan exported. It is not an Android installer or an executable app.');}catch(e){say(e.message);}};
$('builder-voice').onclick=()=>{if(recognition){stopVoice();return;}const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){say('Voice input is unavailable. Type your answer.');return;}try{const active=new Speech();recognition=active;active.lang=$('builder-voice-language').value;active.interimResults=false;active.continuous=false;active.onresult=event=>{if(recognition!==active)return;const spoken=Array.from(event.results).filter(r=>r.isFinal).map(r=>r[0].transcript).join(' ');$('builder-answer').value=[$('builder-answer').value,spoken].filter(Boolean).join(' ');invalidate();say('Voice transcribed. Check the text before continuing.');};active.onerror=event=>{if(recognition!==active)return;say(event.error==='not-allowed'?'Microphone permission was denied. You can type your answer.':'Voice input failed. You can type your answer.');};active.onend=()=>{if(recognition===active){recognition=null;$('builder-voice').textContent='Speak answer';}};active.start();$('builder-voice').textContent='Stop listening';say('Listening for this answer…');}catch{stopVoice();say('Voice input could not start. Type your answer.');}};
